import {
  ActionRowBuilder,
  ButtonBuilder,
  ButtonStyle,
  EmbedBuilder,
  StringSelectMenuBuilder,
} from "discord.js";
import { SettingsStore, BillingActionLevel } from "../config/SettingsStore";
import { BILLING_ACTIONS, actionByKey } from "./billing/actions/ActionRegistry";
import type { IntercomAdmin } from "../intercom/types";

// /config → Billing → Intercom Actions / Intercom Admins panel builders.
// Pure builders (no I/O) so DiscordBot's config router stays thin. Custom-id
// map (all admin-gated by handleConfigButton's existing check):
//   config_bact                     → levels list, page 0
//   config_bact_page:<n>            → levels list, page n
//   config_bact_pick:<n>            → select an action on page n
//   config_bact_view:<key>:<n>      → per-action panel (back returns to page n)
//   config_bact_set:<key>:<level>:<n> → set the level, re-render
//   config_badm                     → admins panel, page 0
//   config_badm_page:<n>            → admins panel, page n
//   config_badm_pick:<n>            → teammate multi-select on page n

export const ACTIONS_PAGE_SIZE = 10;
export const ADMINS_PAGE_SIZE = 25; // Discord select-menu option cap

const LEVEL_LABEL: Record<BillingActionLevel, string> = {
  none: "None (disabled for everyone)",
  approval: "Agent Approval",
  admin: "Admin Only (agents denied)",
  all: "All (agents direct)",
};

function sortedActions() {
  // Group order keeps the list scannable; registry order within a group.
  const groupOrder = ["Reviews", "Charges", "Subscriptions", "Invoices", "Customer"];
  return [...BILLING_ACTIONS].sort((a, b) => groupOrder.indexOf(a.group) - groupOrder.indexOf(b.group));
}

export function buildActionLevelsPanel(settings: SettingsStore, page: number, backTarget = "config_billing") {
  const actions = sortedActions();
  const pages = Math.max(1, Math.ceil(actions.length / ACTIONS_PAGE_SIZE));
  const clamped = Math.min(Math.max(page, 0), pages - 1);
  const slice = actions.slice(clamped * ACTIONS_PAGE_SIZE, (clamped + 1) * ACTIONS_PAGE_SIZE);

  const lines = slice.map((def) => {
    const stored = settings.billingActionLevels()[def.key];
    const level = settings.billingActionLevel(def.key, def.defaultLevel);
    const suffix = stored === undefined ? " _(default)_" : "";
    return `**${def.group} · ${def.label}**: ${LEVEL_LABEL[level]}${suffix}`;
  });

  const embed = new EmbedBuilder()
    .setTitle("Intercom Billing Actions")
    .setColor(0x5865f2)
    .setDescription(
      [
        "Access level per canvas/panel action. **None disables the action for everyone, including admins.**",
        "Agent Approval: agents queue for admin approval, admins execute directly. All: agents execute directly too.",
        "Default is None for every action except Charge review (Agent Approval).",
        "",
        ...lines,
      ].join("\n")
    )
    .setFooter({ text: `Page ${clamped + 1}/${pages}: pick an action below to change its level` });

  const select = new StringSelectMenuBuilder()
    .setCustomId(`config_bact_pick:${clamped}`)
    .setPlaceholder("Pick an action to configure")
    .addOptions(
      slice.map((def) => ({
        label: def.label.slice(0, 100),
        description: `${def.group}: ${LEVEL_LABEL[settings.billingActionLevel(def.key, def.defaultLevel)]}`.slice(0, 100),
        value: def.key,
      }))
    );

  const nav = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId(`config_bact_page:${clamped - 1}`)
      .setLabel("Prev")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(clamped <= 0),
    new ButtonBuilder()
      .setCustomId(`config_bact_page:${clamped + 1}`)
      .setLabel("Next")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(clamped >= pages - 1),
    new ButtonBuilder().setCustomId(backTarget).setLabel("Back").setStyle(ButtonStyle.Secondary)
  );

  return {
    embeds: [embed],
    components: [new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select), nav],
  };
}

export function buildActionDetailPanel(settings: SettingsStore, key: string, page: number) {
  const def = actionByKey(key);
  if (!def) return buildActionLevelsPanel(settings, page);
  const current = settings.billingActionLevel(def.key, def.defaultLevel);
  const stored = settings.billingActionLevels()[def.key];

  const embed = new EmbedBuilder()
    .setTitle(`Action: ${def.label}`)
    .setColor(0x5865f2)
    .setDescription(
      [
        `**Group:** ${def.group}`,
        `**Current level:** ${LEVEL_LABEL[current]}${stored === undefined ? " _(default)_" : ""}`,
        `**Registry default:** ${LEVEL_LABEL[def.defaultLevel]}`,
        def.dangerous ? "**Dangerous:** panel requires typed CONFIRM." : "",
        "",
        "None: nobody can run it (admins included).",
        "Agent Approval: agents queue for admin approval; admins execute directly.",
        "Admin Only: admins execute directly; agents get nothing (not even a queue request).",
        "All: agents execute directly too.",
      ]
        .filter(Boolean)
        .join("\n")
    );

  const levelButton = (level: BillingActionLevel, label: string) =>
    new ButtonBuilder()
      .setCustomId(`config_bact_set:${def.key}:${level}:${page}`)
      .setLabel(label)
      .setStyle(current === level ? ButtonStyle.Success : ButtonStyle.Secondary)
      .setDisabled(current === level);

  const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
    levelButton("none", "None"),
    levelButton("approval", "Agent Approval"),
    levelButton("admin", "Admin Only"),
    levelButton("all", "All"),
    new ButtonBuilder().setCustomId(`config_bact_page:${page}`).setLabel("Back").setStyle(ButtonStyle.Secondary)
  );

  return { embeds: [embed], components: [row] };
}

export function buildIntercomAdminsPanel(
  settings: SettingsStore,
  teammates: IntercomAdmin[] | null, // null = fetch failed
  page: number
, backTarget = "config_billing") {
  const marked = settings.intercomPanelAdmins();
  const lines =
    marked.length > 0
      ? marked.map((a) => `• **${a.name}** (\`${a.id}\`)`)
      : ["_none: nobody can approve or execute admin-gated actions from Intercom (Discord /billing still works)_"];

  const embed = new EmbedBuilder()
    .setTitle("Intercom Billing Admins")
    .setColor(0x5865f2)
    .setDescription(
      [
        "Teammates marked here count as **admins** for canvas/panel billing actions: they execute directly where the level is Agent Approval and act on the approval queue.",
        "Everyone else with inbox access is a support agent.",
        "",
        "**Currently marked:**",
        ...lines,
      ].join("\n")
    );

  const components: Array<ActionRowBuilder<StringSelectMenuBuilder> | ActionRowBuilder<ButtonBuilder>> = [];
  let pages = 1;
  let clamped = 0;
  if (teammates === null) {
    embed.addFields({
      name: "Teammate list unavailable",
      value: "Could not fetch the workspace teammates from Intercom. Check the Intercom connection in /config → Intercom.",
    });
  } else if (teammates.length === 0) {
    embed.addFields({ name: "No teammates", value: "The Intercom workspace returned no teammates." });
  } else {
    pages = Math.max(1, Math.ceil(teammates.length / ADMINS_PAGE_SIZE));
    clamped = Math.min(Math.max(page, 0), pages - 1);
    const slice = teammates.slice(clamped * ADMINS_PAGE_SIZE, (clamped + 1) * ADMINS_PAGE_SIZE);
    const markedIds = new Set(marked.map((a) => a.id));
    const select = new StringSelectMenuBuilder()
      .setCustomId(`config_badm_pick:${clamped}`)
      .setPlaceholder("Select the teammates who count as admins")
      .setMinValues(0)
      .setMaxValues(slice.length)
      .addOptions(
        slice.map((t) => ({
          label: (t.name || `Teammate ${t.id}`).slice(0, 100),
          description: (t.email ?? t.id).slice(0, 100),
          value: t.id,
          default: markedIds.has(t.id),
        }))
      );
    components.push(new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select));
    if (pages > 1) embed.setFooter({ text: `Teammates page ${clamped + 1}/${pages}: selection saves per page` });
  }

  const nav = new ActionRowBuilder<ButtonBuilder>().addComponents(
    ...(teammates && pages > 1
      ? [
          new ButtonBuilder()
            .setCustomId(`config_badm_page:${clamped - 1}`)
            .setLabel("Prev")
            .setStyle(ButtonStyle.Secondary)
            .setDisabled(clamped <= 0),
          new ButtonBuilder()
            .setCustomId(`config_badm_page:${clamped + 1}`)
            .setLabel("Next")
            .setStyle(ButtonStyle.Secondary)
            .setDisabled(clamped >= pages - 1),
        ]
      : []),
    new ButtonBuilder().setCustomId(backTarget).setLabel("Back").setStyle(ButtonStyle.Secondary)
  );
  components.push(nav);

  return { embeds: [embed], components };
}

// Per-page merge for the admins multi-select: keep marked teammates that are
// NOT on the rendered page, replace the page's subset with the selection.
export function mergeAdminSelection(
  settings: SettingsStore,
  teammates: IntercomAdmin[],
  page: number,
  selectedIds: string[]
): Array<{ id: string; name: string }> {
  const slice = teammates.slice(page * ADMINS_PAGE_SIZE, (page + 1) * ADMINS_PAGE_SIZE);
  const pageIds = new Set(slice.map((t) => t.id));
  const byId = new Map(teammates.map((t) => [t.id, t.name || `Teammate ${t.id}`]));
  const kept = settings.intercomPanelAdmins().filter((a) => !pageIds.has(a.id));
  const added = selectedIds.filter((id) => pageIds.has(id)).map((id) => ({ id, name: byId.get(id) ?? id }));
  return [...kept, ...added];
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { AdminPanel } from "../AdminPanel";
import { renderAdminShell } from "../adminPanelHtml";

// The merged panel runs the whole admin surface behind ONE login. That makes
// the bridge from a billing-dashboard session into a config-panel session a
// security boundary, so these assert what it refuses, not what it allows.

const settings = {
  adminPanelEpoch: () => 1,
} as never;

// Never returns a session of its own: every case here exercises the bridge.
const sessions = { get: () => null } as never;

function panelWith(auth: { actor: { id: string; name: string; isAdmin: boolean }; state: string } | null) {
  const panel = new AdminPanel(settings, {} as never, sessions, {} as never, [], undefined);
  panel.bindSharedAuth({ authenticate: async () => auth });
  return panel;
}

test("shared login: an active admin dashboard session opens the config panel without a second unlock", async () => {
  // The dashboard login was earned with a passkey or a hardware key, which is a
  // stronger factor than this panel's Discord passcode. A second ceremony would
  // be theatre.
  const panel = panelWith({ actor: { id: "42", name: "Ada", isAdmin: true }, state: "active" });
  const res = (await panel.api("activation-status", "cookie", {})) as { status: number; json: Record<string, unknown> };
  assert.equal(res.status, 200);
  assert.equal(res.json.state, "active");
  assert.equal(res.json.adminName, "Ada");
  assert.ok(!("activationCode" in res.json), "an already-active session is never asked to activate");
});

test("shared login: a LOCKED dashboard session is refused", async () => {
  // A locked session has not finished logging in. Accepting it would let a
  // half-authenticated browser read configuration through the side door.
  const panel = panelWith({ actor: { id: "42", name: "Ada", isAdmin: true }, state: "locked" });
  const res = (await panel.api("activation-status", "cookie", {})) as { json: Record<string, unknown> };
  assert.equal(res.json.state, "expired");
});

test("shared login: a non-admin dashboard session is refused", async () => {
  // The dashboard has read-only roles. Those must not reach /config, which can
  // change refund caps and dispute automation.
  const panel = panelWith({ actor: { id: "7", name: "Viewer", isAdmin: false }, state: "active" });
  const res = (await panel.api("activation-status", "cookie", {})) as { json: Record<string, unknown> };
  assert.equal(res.json.state, "expired");
});

test("shared login: no dashboard session and no panel session means no access", async () => {
  const panel = panelWith(null);
  const res = (await panel.api("activation-status", "cookie", {})) as { json: Record<string, unknown> };
  assert.equal(res.json.state, "expired");

  // And an unbound bridge behaves exactly like an absent one.
  const unbound = new AdminPanel(settings, {} as never, sessions, {} as never, [], undefined);
  const res2 = (await unbound.api("activation-status", "cookie", {})) as { json: Record<string, unknown> };
  assert.equal(res2.json.state, "expired");
});

test("shared login: a bridged session carries no destructive challenge", async () => {
  // Destructive ceremonies mint their code through this panel's own Discord
  // path, which a dashboard login never walked. They stay available on a native
  // panel session and are simply unavailable on a bridged one.
  const panel = panelWith({ actor: { id: "42", name: "Ada", isAdmin: true }, state: "active" });
  const res = (await panel.api("activation-status", "cookie", {})) as { json: Record<string, unknown> };
  assert.equal(res.json.state, "active");
});

// The merged entry point: /panel/config is reached by clicking a nav item, so
// there is no link token to present and page() has to decide on the cookie
// alone. That makes the PAGE a second copy of the same boundary as the api.

test("merged entry: an active admin dashboard session is served the shell without a token", async () => {
  const panel = panelWith({ actor: { id: "42", name: "Ada", isAdmin: true }, state: "active" });
  const res = (await panel.page("", "dash-session", { basePath: "/panel/config" })) as { html: string };
  assert.ok(res.html, "the shell is served");
  // The shell must post back to the mount it came from: that mount is the one
  // reading the dashboard cookie, so a hard-coded /admin/panel/api would
  // authenticate against the wrong cookie and look expired.
  assert.match(res.html, /"\/panel\/config\/api\/"/);
  assert.match(res.html, /Back to dashboard/);
});

test("merged entry: a locked or non-admin dashboard session is refused the shell", async () => {
  for (const auth of [
    { actor: { id: "42", name: "Ada", isAdmin: true }, state: "locked" },
    { actor: { id: "7", name: "Viewer", isAdmin: false }, state: "active" },
  ]) {
    const res = (await panelWith(auth).page("", "dash-session", { basePath: "/panel/config" })) as { status: number };
    assert.equal(res.status, 401);
  }
});

test("merged entry: no session is refused, and the bridge is scoped to the merged mount", async () => {
  const none = (await panelWith(null).page("", "dash-session", { basePath: "/panel/config" })) as { status: number };
  assert.equal(none.status, 401);

  // The standalone mount is handed THIS panel's cookie, never a dashboard one,
  // so it must not resolve a dashboard session id: a session id from one
  // namespace has no business being looked up in the other.
  const panel = panelWith({ actor: { id: "42", name: "Ada", isAdmin: true }, state: "active" });
  const boot = (await panel.page("", "dash-session", { basePath: "/admin/panel" })) as { status: number };
  assert.equal(boot.status, 401);
});

test("the bootstrap shell posts to its own api path and offers no way back", () => {
  // Reached without a dashboard login, so there is nothing to go back to.
  const html = renderAdminShell({ nonce: "N", apiBase: "/admin/panel" });
  assert.match(html, /"\/admin\/panel\/api\/"/);
  assert.ok(!/Back to dashboard/.test(html), "no back link on the standalone mount");
});

import {
  generateAuthenticationOptions,
  generateRegistrationOptions,
  verifyAuthenticationResponse,
  verifyRegistrationResponse,
} from "@simplewebauthn/server";
import type {
  AuthenticationResponseJSON,
  RegistrationResponseJSON,
  WebAuthnCredential,
} from "@simplewebauthn/server";

// Thin passkey layer for the dashboard: option generation, response
// verification and the single-use challenge ledger. RP identity derives from
// resolvedPublicBaseUrl() — rpID is its hostname, expectedOrigin the full
// origin, so the passkey assertion is cryptographically bound to OUR origin
// (this is what makes the login phishing-immune).

const CHALLENGE_TTL_MS = 2 * 60 * 1000;
const MAX_CHALLENGES = 200;

export interface RpIdentity {
  rpID: string; // hostname, e.g. "bot.example.com"
  origin: string; // "https://bot.example.com"
  rpName: string;
}

export function rpFromBaseUrl(baseUrl: string | null): RpIdentity | null {
  if (!baseUrl) return null;
  try {
    const u = new URL(baseUrl);
    return { rpID: u.hostname, origin: u.origin, rpName: "Billing dashboard" };
  } catch {
    return null;
  }
}

// Outstanding WebAuthn challenges — in-memory, single-use, 2-min TTL. The
// challenge string itself is the key (it is server-generated 32-byte random).
export class ChallengeStore {
  private challenges = new Map<string, number>();

  remember(challenge: string): void {
    this.prune();
    while (this.challenges.size >= MAX_CHALLENGES) {
      const oldest = this.challenges.keys().next().value;
      if (oldest === undefined) break;
      this.challenges.delete(oldest);
    }
    this.challenges.set(challenge, Date.now());
  }

  // True exactly once per challenge, inside the TTL.
  consume(challenge: string): boolean {
    this.prune();
    if (!this.challenges.has(challenge)) return false;
    this.challenges.delete(challenge);
    return true;
  }

  private prune(): void {
    const cutoff = Date.now() - CHALLENGE_TTL_MS;
    for (const [c, at] of this.challenges) {
      if (at < cutoff) this.challenges.delete(c);
    }
  }
}

export async function makeRegistrationOptions(
  rp: RpIdentity,
  userName: string,
  excludeCredentialIds: string[]
): Promise<{ options: Awaited<ReturnType<typeof generateRegistrationOptions>>; challenge: string }> {
  const options = await generateRegistrationOptions({
    rpName: rp.rpName,
    rpID: rp.rpID,
    userName,
    attestationType: "none",
    excludeCredentials: excludeCredentialIds.map((id) => ({ id })),
    authenticatorSelection: {
      // Discoverable credential + user verification: one-touch usernameless
      // login, biometric/PIN required.
      residentKey: "required",
      userVerification: "required",
    },
  });
  return { options, challenge: options.challenge };
}

export async function checkRegistration(
  rp: RpIdentity,
  response: RegistrationResponseJSON,
  expectedChallenge: string
): Promise<{ credential: WebAuthnCredential; backedUp: boolean } | null> {
  try {
    const result = await verifyRegistrationResponse({
      response,
      expectedChallenge,
      expectedOrigin: rp.origin,
      expectedRPID: rp.rpID,
      requireUserVerification: true,
    });
    if (!result.verified || !result.registrationInfo) return null;
    return { credential: result.registrationInfo.credential, backedUp: result.registrationInfo.credentialBackedUp };
  } catch {
    return null;
  }
}

export async function makeAuthenticationOptions(
  rp: RpIdentity
): Promise<{ options: Awaited<ReturnType<typeof generateAuthenticationOptions>>; challenge: string }> {
  // No allowCredentials: discoverable credentials make the browser offer
  // whatever passkeys exist for this rpID (usernameless, no enumeration).
  const options = await generateAuthenticationOptions({ rpID: rp.rpID, userVerification: "required" });
  return { options, challenge: options.challenge };
}

export async function checkAuthentication(
  rp: RpIdentity,
  response: AuthenticationResponseJSON,
  expectedChallenge: string,
  credential: WebAuthnCredential
): Promise<{ newCounter: number } | null> {
  try {
    const result = await verifyAuthenticationResponse({
      response,
      expectedChallenge,
      expectedOrigin: rp.origin,
      expectedRPID: rp.rpID,
      credential,
      requireUserVerification: true,
    });
    if (!result.verified) return null;
    return { newCounter: result.authenticationInfo.newCounter };
  } catch {
    return null;
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { QueueAuth, type QueueAuthSettings, type QueueRefusalAudit } from "../QueueAuth";
import { QueueSessions, type QueueSessionDb } from "../QueueSessions";
import type { QueueTeammate } from "../QueueData";

// "Sign in with Intercom": the state is single-use and bound to the pre-login
// cookie, the identity must be verified, in our workspace and seated, the
// OAuth token never leaves the exchange, and a session dies when the teammate
// does. Intercom and the database are fakes.

type Row = Record<string, unknown> & { id: string };

function matches(row: Row, where: Record<string, unknown> | undefined): boolean {
  if (!where) return true;
  for (const [k, cond] of Object.entries(where)) {
    if (k === "OR") {
      if (!(cond as Array<Record<string, unknown>>).some((w) => matches(row, w))) return false;
      continue;
    }
    const v = row[k];
    if (cond && typeof cond === "object" && !(cond instanceof Date)) {
      const c = cond as { lt?: Date; gt?: Date; in?: string[] };
      if (c.in && !c.in.includes(v as string)) return false;
      if (c.lt && !((v as Date).getTime() < c.lt.getTime())) return false;
      if (c.gt && !((v as Date).getTime() > c.gt.getTime())) return false;
    } else if (v !== cond) return false;
  }
  return true;
}

function fakeDb(): { db: QueueSessionDb; rows: Map<string, Row> } {
  const rows = new Map<string, Row>();
  const qs = {
    create: async ({ data }: { data: Row }) => {
      rows.set(data.id, { ...data });
      return data;
    },
    findUnique: async ({ where }: { where: { id: string } }) => (rows.has(where.id) ? { ...rows.get(where.id)! } : null),
    update: async ({ where, data }: { where: { id: string }; data: Record<string, unknown> }) => {
      const r = rows.get(where.id);
      if (!r) throw new Error("not found");
      Object.assign(r, data);
      return r;
    },
    updateMany: async ({ where, data }: { where: Record<string, unknown>; data: Record<string, unknown> }) => {
      let count = 0;
      for (const r of rows.values()) if (matches(r, where)) (Object.assign(r, data), count++);
      return { count };
    },
    deleteMany: async (args?: { where?: Record<string, unknown> }) => {
      let count = 0;
      for (const [id, r] of [...rows]) if (matches(r, args?.where)) (rows.delete(id), count++);
      return { count };
    },
    findMany: async (args: { where?: Record<string, unknown>; take?: number }) => {
      const list = [...rows.values()].filter((r) => matches(r, args.where)).sort((a, b) => (a.createdAt as Date).getTime() - (b.createdAt as Date).getTime());
      return (args.take ? list.slice(0, args.take) : list).map((r) => ({ id: r.id }));
    },
    count: async (args?: { where?: Record<string, unknown> }) => [...rows.values()].filter((r) => matches(r, args?.where)).length,
  };
  return { db: { queueSession: qs } as unknown as QueueSessionDb, rows };
}

const NOW = 2_000_000_000_000;

function setup(opts: { me?: Record<string, unknown>; tokenStatus?: number; ready?: boolean; enabled?: boolean } = {}) {
  let now = NOW;
  const state = { enabled: opts.enabled ?? true, ready: opts.ready ?? true, epoch: 0 };
  const settings: QueueAuthSettings = {
    queueEnabled: () => state.enabled,
    queueReady: () => state.ready,
    queueOauthClientId: () => "client-123",
    queueOauthClientSecret: () => "secret-xyz-123",
    queueEpoch: () => state.epoch,
    intercomRegion: () => "us",
    resolvedPublicBaseUrl: () => "https://bot.example.com/",
  };
  const teammates = new Map<string, QueueTeammate>([["11", { id: "11", name: "Ada", seated: true, away: false, bot: false }]]);
  const directory = {
    down: false,
    async seatedTeammate(id: string) {
      if (directory.down) throw new Error("intercom down");
      return teammates.get(id) ?? null;
    },
    async workspaceIdCode() {
      return "abcd1234";
    },
  };
  const { db, rows } = fakeDb();
  const sessions = new QueueSessions(db, () => now);
  const audits: QueueRefusalAudit[] = [];
  const calls: Array<{ url: string; init: RequestInit }> = [];
  const me = opts.me ?? { id: 11, name: "Ada", email: "ada@example.test", email_verified: true, app: { id_code: "abcd1234" } };
  const fetchFn = async (url: string, init: RequestInit): Promise<Response> => {
    calls.push({ url, init });
    if (url.endsWith("/auth/eagle/token")) {
      const status = opts.tokenStatus ?? 200;
      return new Response(JSON.stringify(status === 200 ? { token_type: "Bearer", access_token: "[REDACTED]" } : { error: "bad" }), { status });
    }
    if (url.endsWith("/me")) return new Response(JSON.stringify(me), { status: 200 });
    return new Response("{}", { status: 404 });
  };
  const auth = new QueueAuth(settings, directory, sessions, (e) => audits.push(e), fetchFn, () => now);
  return { auth, state, teammates, directory, rows, audits, calls, advance: (ms: number) => (now += ms) };
}

function cookieValue(setCookies: string[], name: string): string {
  const c = setCookies.find((x) => x.startsWith(`${name}=`));
  assert.ok(c, `cookie ${name}`);
  return c.slice(name.length + 1).split(";")[0];
}

function startFlow(auth: QueueAuth): { state: string; nonce: string } {
  const r = auth.start();
  assert.equal(r.status, 302);
  if (r.status !== 302) throw new Error("unreachable");
  const url = new URL(r.location);
  return { state: url.searchParams.get("state")!, nonce: cookieValue(r.setCookies, "__Host-queue-oauth") };
}

test("start: 404 while off, the config error while not ready, else Intercom's consent page", () => {
  assert.equal(setup({ enabled: false }).auth.start().status, 404);
  const notReady = setup({ ready: false }).auth.start();
  assert.deepEqual(notReady, { status: 302, location: "/queue?e=config", setCookies: [] });

  const { auth } = setup();
  const r = auth.start();
  assert.equal(r.status, 302);
  if (r.status !== 302) return;
  const url = new URL(r.location);
  assert.equal(url.origin + url.pathname, "https://app.intercom.com/oauth");
  assert.equal(url.searchParams.get("client_id"), "client-123");
  assert.equal(url.searchParams.get("redirect_uri"), "https://bot.example.com/queue/oauth/callback");
  assert.ok((url.searchParams.get("state") ?? "").length >= 30);
  const cookie = r.setCookies[0];
  assert.match(cookie, /^__Host-queue-oauth=[A-Za-z0-9_-]+; Path=\/; Secure; HttpOnly; SameSite=Lax; Max-Age=600$/);
});

test("callback: a verified teammate of our workspace gets a session; the OAuth token is used once and dropped", async () => {
  const { auth, rows, calls, audits } = setup();
  const { state, nonce } = startFlow(auth);
  const r = await auth.callback({ code: "auth-code-1", state }, nonce, { ip: "1.2.3.4", ua: "UA" });
  assert.equal(r.status, 302);
  if (r.status !== 302) return;
  assert.equal(r.location, "/queue");
  const session = cookieValue(r.setCookies, "__Host-queue");
  assert.ok(session.length > 30);
  assert.ok(r.setCookies.some((c) => c.startsWith("__Host-queue-oauth=;") && c.includes("Max-Age=0")), "the state cookie is cleared");
  assert.equal(rows.size, 1);
  const row = [...rows.values()][0];
  assert.equal(row.adminId, "11");
  assert.notEqual(row.id, session, "only the hash is stored");
  assert.ok(!JSON.stringify(row).includes("user-token-1"), "the OAuth token is never stored");

  const exchange = calls.find((c) => c.url === "https://api.intercom.io/auth/eagle/token")!;
  const body = new URLSearchParams(String(exchange.init.body));
  assert.equal(body.get("code"), "auth-code-1");
  assert.equal(body.get("client_id"), "client-123");
  assert.equal(body.get("client_secret"), "secret-xyz-123");
  const me = calls.find((c) => c.url === "https://api.intercom.io/me")!;
  assert.equal((me.init.headers as Record<string, string>).Authorization, "Bearer user-token-1");
  assert.equal(audits.length, 0);

  const actor = await auth.authenticate(session);
  assert.equal(actor?.adminId, "11");
  assert.equal(actor?.name, "Ada");
});

test("callback: a replayed or foreign state is refused and audited", async () => {
  const { auth, audits } = setup();
  const { state, nonce } = startFlow(auth);
  const first = await auth.callback({ code: "c1", state }, nonce, {});
  assert.equal(first.status === 302 && first.location, "/queue");
  const replay = await auth.callback({ code: "c1", state }, nonce, {});
  assert.equal(replay.status === 302 && replay.location, "/queue?e=expired");
  assert.equal(audits.length, 1);

  // A state started in another browser (no matching cookie).
  const other = startFlow(auth);
  const csrf = await auth.callback({ code: "c2", state: other.state }, "attacker-nonce", { ip: "9.9.9.9" });
  assert.equal(csrf.status === 302 && csrf.location, "/queue?e=expired");
  assert.equal(audits[1].ip, "9.9.9.9");
});

