import type Stripe from "stripe";
import { Prisma, PrismaClient, StripeDispute } from "../../generated/prisma/client";
import { emitDisputeOutcome } from "../../metrics/MetricsExporter";
import { usdMinorOf } from "./fx";
import type { StripeSegmentResolver } from "./StripeSegmentResolver";
import type { MoneySegments } from "./segments";

// Statuses with staff work left to do — everything the overview lists.
export const OPEN_DISPUTE_STATUSES = [
  "warning_needs_response",
  "warning_under_review",
  "needs_response",
  "under_review",
] as const;

// A response can still be submitted only in these two.
export const RESPONDABLE_DISPUTE_STATUSES = ["needs_response", "warning_needs_response"] as const;

// Stripe reads one live dispute upsert may spend on its descriptive segments:
// the charge, its invoice, the subscription behind it, and the customer's age.
// The resolver caches across calls, so a burst of webhooks for one dispute
// spends this once, not once per delivery.
const LIVE_SEGMENT_BUDGET = 4;

// The stored segment columns, back in the shape the exporter wants. Exported so
// the history backfill can re-emit outcome points with their axes intact
// without re-reading anything from Stripe.
export function segmentsOfDispute(row: {
  planTier: string | null;
  planPeriod: string | null;
  cardBrand: string | null;
  cardFunding: string | null;
  cardCountry: string | null;
  networkReason: string | null;
  tenure: string | null;
}): MoneySegments {
  return {
    planTier: row.planTier,
    planPeriod: row.planPeriod,
    cardBrand: row.cardBrand,
    cardFunding: row.cardFunding,
    cardCountry: row.cardCountry,
    networkReason: row.networkReason,
    tenure: row.tenure,
  };
}

// When a dispute closed, and how sure we are.
//
// Stripe exposes no closed-at timestamp, so this is inferred unless an
// authoritative source says otherwise. Three cases, in priority order:
//
//   closedAtExact  — a real moment, from Stripe's own events. Overwrites a
//                    stored estimate, which is the whole point: closedAt is
//                    otherwise write-once, so a first bad guess would be
//                    permanent and the estimate could never be improved.
//   stored         — already decided; an estimate stays put rather than
//                    drifting every time a webhook re-reads the dispute.
//   hint / now     — the backfill's guess, or "we saw it close just now",
//                    which is accurate for a live transition and is therefore
//                    recorded as observed rather than estimated.
function closedAtColumns(
  terminal: boolean,
  existing: StripeDispute | null,
  opts?: { closedAtHint?: Date; closedAtExact?: { at: Date; source: string } }
): { closedAt: Date | null; closedAtEstimated?: boolean; closedAtSource?: string } {
  if (!terminal) return { closedAt: null };
  if (opts?.closedAtExact) {
    return {
      closedAt: opts.closedAtExact.at,
      closedAtEstimated: false,
      closedAtSource: opts.closedAtExact.source,
    };
  }
  if (existing?.closedAt) return { closedAt: existing.closedAt };
  if (opts?.closedAtHint) {
    return { closedAt: opts.closedAtHint, closedAtEstimated: true, closedAtSource: "backfill_guess" };
  }
  // We watched it happen, so the time is real even though Stripe never said it.
  return { closedAt: new Date(), closedAtEstimated: false, closedAtSource: "observed" };
}

function usdColumns(amountMinor: number, currency: string): { usdMinor?: number; fxRate?: number } {
  const usd = usdMinorOf(amountMinor, currency);
  return usd ? { usdMinor: usd.usdMinor, fxRate: usd.rate } : {};
}

// Terminal states never regress: a late-delivered charge.dispute.updated must
// not flip a closed dispute back to under_review (webhooks are unordered).
const TERMINAL_STATUSES = new Set(["won", "lost", "prevented", "warning_closed"]);
export const TERMINAL_DISPUTE_STATUSES = TERMINAL_STATUSES;

// Every TEXT evidence field Stripe accepts on a dispute (file slots excluded —
// those hold file_… ids). Canonical list shared by the evidence editor groups
// and the evidenceFinal snapshot taken once evidence is submitted.
export const TEXT_EVIDENCE_KEYS = [
  "access_activity_log",
  "billing_address",
  "cancellation_policy_disclosure",
  "cancellation_rebuttal",
  "customer_email_address",
  "customer_name",
  "customer_purchase_ip",
  "duplicate_charge_explanation",
  "duplicate_charge_id",
  "product_description",
  "refund_policy_disclosure",
  "refund_refusal_explanation",
  "service_date",
  "shipping_address",
  "shipping_carrier",
  "shipping_date",
  "shipping_tracking_number",
  "uncategorized_text",
] as const;

// The axes the loss breakdown can group decided chargebacks by.
export type LossAxis = "reason" | "networkReason" | "cardBrand" | "verdict" | "decisive";

// Overview filter/sort state (kept in the panel session).
export type DisputeSort = "due" | "amount" | "new";
export interface OpenDisputeFilter {
  status?: string; // one of OPEN_DISPUTE_STATUSES
  reason?: string;
}
export type ClosedOutcome = "won" | "lost" | "other";
export interface ClosedDisputeFilter {
  outcome?: ClosedOutcome;
  reason?: string;
}

export interface OutcomeStats {
  won: number;
  lost: number;
  other: number; // prevented + warning_closed
  winRatePct: number | null; // won / (won + lost); null when no decided disputes
  // Minor units per currency — mixed-currency accounts can't be summed as one.
  wonAmount: Record<string, number>;
  lostAmount: Record<string, number>;
  lostUnanswered: number; // lost without any evidence submission
}

export interface ReasonStats {
  reason: string;
  won: number;
  lost: number;
  other: number;
  winRatePct: number | null;
}

const OTHER_CLOSED_STATUSES = ["prevented", "warning_closed"];

function closedStatusFilter(outcome: ClosedOutcome | undefined): string[] {
  if (outcome === "won") return ["won"];
  if (outcome === "lost") return ["lost"];
  if (outcome === "other") return OTHER_CLOSED_STATUSES;
  return [...TERMINAL_STATUSES];
}

// Text evidence as currently visible on the Stripe dispute object — the
// snapshot stored as evidenceFinal once a submission exists, so future AI
// drafts can learn from evidence that actually won.
function snapshotTextEvidence(d: Stripe.Dispute): Record<string, string> | null {
  const evidence = d.evidence as unknown as Record<string, unknown> | null | undefined;
  if (!evidence) return null;
  const out: Record<string, string> = {};
  for (const key of TEXT_EVIDENCE_KEYS) {
    const value = evidence[key];
    if (typeof value === "string" && value.trim()) out[key] = value;
  }
  return Object.keys(out).length ? out : null;
}

export const DAY_MS = 24 * 60 * 60 * 1000;

// Local mirror of Stripe disputes. Stripe's disputes.list can't filter by
// status, so the open-disputes overview and the reminder looper read from
// here; webhooks and the looper reconciliation keep it fresh.
export class DisputeStore {
  // Optional, bound after construction (same idiom as the Discord client
  // bindings elsewhere): the store is built before the Stripe client exists.
  // Unbound, every dispute simply keeps null segments and charts as "unknown".
  private segments: StripeSegmentResolver | null = null;

  constructor(private prisma: PrismaClient) {}

  bindSegments(resolver: StripeSegmentResolver): void {
    this.segments = resolver;
  }

  // Idempotent upsert from a live Stripe dispute (webhook or reconciliation).
  // due_by can be null or 0 (bank allows no response) — both map to null.
  // closedAtHint: historical close estimate used by the backfill for disputes
  // that closed before the mirror existed (otherwise "first seen closed" = now).
  async upsertFromStripe(
    d: Stripe.Dispute,
    customerId: string | null,
    opts?: {
      closedAtHint?: Date;
      // Stripe reads this upsert may spend resolving the descriptive segments.
      // undefined = the live default (a handful, mostly served from cache);
      // null = do not touch the budget, because the CALLER opened one for a
      // whole batch (the history backfill does exactly that, so one bounded
      // budget covers every dispute instead of each one getting a fresh
      // allowance and the sweep costing reads without limit).
      enrichBudget?: number | null;
      // An AUTHORITATIVE close time, which replaces whatever is stored.
      //
      // Distinct from closedAtHint, which only fills a blank: closedAt is
      // otherwise write-once (`existing?.closedAt ?? …`), so a first, bad guess
      // is permanent and there is no way to improve it later. The rebuild
      // derives the real moment from Stripe's own events, within their 30-day
      // retention, and this is how that gets in.
      closedAtExact?: { at: Date; source: string };
      // Suppress the outcome point for this upsert. The analytics rebuild
      // repairs the whole mirror with emission off and then re-emits the
      // finished state in one pass; a point written mid-repair would be built
      // from half-corrected tags.
      silent?: boolean;
    }
  ): Promise<StripeDispute> {
    const chargeId = typeof d.charge === "string" ? d.charge : (d.charge?.id ?? "");
    const paymentIntentId =
      typeof d.payment_intent === "string" ? d.payment_intent : (d.payment_intent?.id ?? null);
    const evidenceDueBy = d.evidence_details?.due_by ? new Date(d.evidence_details.due_by * 1000) : null;
    const submitted = (d.evidence_details?.submission_count ?? 0) > 0;
    const terminal = TERMINAL_STATUSES.has(d.status);

    const existing = await this.prisma.stripeDispute.findUnique({ where: { id: d.id } });
    if (existing && TERMINAL_STATUSES.has(existing.status) && !terminal) return existing; // stale event

    const segments = await this.resolveSegments(d, existing, opts?.enrichBudget);

    const finalSnapshot = submitted ? snapshotTextEvidence(d) : null;
    const shared = {
      chargeId,
      paymentIntentId,
      customerId: customerId ?? existing?.customerId ?? null,
      amount: d.amount,
      currency: d.currency,
      reason: d.reason || "unknown",
      status: d.status,
      evidenceDueBy,
      // Evidence submitted outside the bot (Dashboard) still gets stamped here.
      evidenceSubmittedAt: submitted ? (existing?.evidenceSubmittedAt ?? new Date()) : existing?.evidenceSubmittedAt ?? null,
      // Submitted text evidence snapshot — kept once captured (the dispute
      // object stops carrying useful evidence long after closing? it doesn't,
      // but an empty read must not wipe a previous snapshot).
      evidenceFinal: finalSnapshot ?? (existing?.evidenceFinal as Prisma.InputJsonValue | undefined) ?? undefined,
      ...closedAtColumns(terminal, existing, opts),
      // The frozen USD conversion, so a dispute_outcomes point can be summed
      // across currencies. Converted once, with the rate kept, and never
      // recomputed: `amount` and `currency` cannot change on a dispute, so a
      // row that already has one keeps it.
      ...(existing?.fxRate != null ? {} : usdColumns(d.amount, d.currency)),
      // Never blank out an axis a previous pass resolved: a lookup that ran out
      // of budget returns undefined here and leaves the stored value alone.
      planTier: segments?.planTier ?? undefined,
      planPeriod: segments?.planPeriod ?? undefined,
      cardBrand: segments?.cardBrand ?? undefined,
      cardFunding: segments?.cardFunding ?? undefined,
      cardCountry: segments?.cardCountry ?? undefined,
      networkReason: segments?.networkReason ?? undefined,
      tenure: segments?.tenure ?? undefined,
    };
    const row = await this.prisma.stripeDispute.upsert({
      where: { id: d.id },
      update: shared,
      create: { ...shared, id: d.id, disputeCreatedAt: new Date(d.created * 1000) },
    });
    // Outcome analytics point on the tracked open → terminal transition only.
    // Disputes first seen already-closed are covered by the history backfill
    // (which emits at their historical closedAt) — emitting them here would
    // burst a fresh deploy's first reconcile at "now".
    //
    // Emitted from `row`, the value Postgres just returned, so this point and
    // the one a later rebuild produces are identical by construction.
    if (!opts?.silent && existing && !TERMINAL_STATUSES.has(existing.status) && terminal) {
      emitDisputeOutcome(row);
    }
    return row;
  }

  // Who disputed us, described without identifying them. Skipped entirely when
  // no resolver is bound, and skipped for a dispute whose axes are already
  // known: they describe the charge behind it, which cannot change.
  private async resolveSegments(
    d: Stripe.Dispute,
    existing: StripeDispute | null,
    budget: number | null | undefined
  ): Promise<MoneySegments | null> {
    const resolver = this.segments;
    if (!resolver) return null;
    if (existing?.planTier && existing.cardBrand) return null;
    if (budget !== null) resolver.startBatch(budget ?? LIVE_SEGMENT_BUDGET);
    try {
      return await resolver.forDispute(d, new Date(d.created * 1000));
    } catch {
      // A chart axis never fails a dispute mirror write.
      return null;
    }
  }

  async get(id: string): Promise<StripeDispute | null> {
    return this.prisma.stripeDispute.findUnique({ where: { id } });
  }

  // Overview page: open disputes, defaulting to most urgent (earliest evidence
  // deadline) first; the panel can filter by status/reason and re-sort.
  async listOpen(
    skip: number,
    take: number,
    filter?: OpenDisputeFilter,
    sort: DisputeSort = "due"
  ): Promise<{ rows: StripeDispute[]; total: number }> {
    const where = {
      status: filter?.status ? filter.status : { in: [...OPEN_DISPUTE_STATUSES] },
      ...(filter?.reason ? { reason: filter.reason } : {}),
    };
    const orderBy: Prisma.StripeDisputeOrderByWithRelationInput[] =
      sort === "amount"
        ? [{ amount: "desc" }, { disputeCreatedAt: "desc" }]
        : sort === "new"
          ? [{ disputeCreatedAt: "desc" }]
          : [{ evidenceDueBy: { sort: "asc", nulls: "last" } }, { disputeCreatedAt: "desc" }];
    const [rows, total] = await Promise.all([
      this.prisma.stripeDispute.findMany({ where, orderBy, skip, take }),
      this.prisma.stripeDispute.count({ where }),
    ]);
    return { rows, total };
  }

  // Stripe panel: all mirrored disputes for one customer, newest first.
  async listByCustomer(customerId: string, take = 10): Promise<StripeDispute[]> {
    return this.prisma.stripeDispute.findMany({
      where: { customerId },
      orderBy: { disputeCreatedAt: "desc" },
      take,
    });
  }

  // Reasons present among open disputes — feeds the overview's filter select.
  async openReasons(): Promise<Array<{ reason: string; count: number }>> {
    const rows = await this.prisma.stripeDispute.groupBy({
      by: ["reason"],
      where: { status: { in: [...OPEN_DISPUTE_STATUSES] } },
      _count: { _all: true },
      orderBy: { _count: { id: "desc" } },
    });
    return rows.map((r) => ({ reason: r.reason, count: r._count._all }));
  }

  // History browser: closed disputes, most recently closed first.
  async listClosed(
    skip: number,
    take: number,
    filter?: ClosedDisputeFilter
  ): Promise<{ rows: StripeDispute[]; total: number }> {
    const where = {
      status: { in: closedStatusFilter(filter?.outcome) },
      ...(filter?.reason ? { reason: filter.reason } : {}),
    };
    const [rows, total] = await Promise.all([
      this.prisma.stripeDispute.findMany({
        where,
        orderBy: [{ closedAt: { sort: "desc", nulls: "last" } }, { disputeCreatedAt: "desc" }],
        skip,
        take,
      }),
      this.prisma.stripeDispute.count({ where }),
    ]);
    return { rows, total };
  }

  async closedReasons(): Promise<Array<{ reason: string; count: number }>> {
    const rows = await this.prisma.stripeDispute.groupBy({
      by: ["reason"],
      where: { status: { in: [...TERMINAL_STATUSES] } },
      _count: { _all: true },
      orderBy: { _count: { id: "desc" } },
    });
    return rows.map((r) => ({ reason: r.reason, count: r._count._all }));
  }

  // Outcome aggregates for the analytics panel. closedSince = undefined →
  // all-time; otherwise only disputes closed in the trailing window.
  async outcomeStats(closedSinceDays?: number, now: Date = new Date()): Promise<OutcomeStats> {
    const closedWindow = closedSinceDays
      ? { closedAt: { gte: new Date(now.getTime() - closedSinceDays * DAY_MS) } }
      : {};
    const where = { status: { in: [...TERMINAL_STATUSES] }, ...closedWindow };
    const [byStatusCurrency, lostUnanswered] = await Promise.all([
      this.prisma.stripeDispute.groupBy({
        by: ["status", "currency"],
        where,
        _count: { _all: true },
        _sum: { amount: true },
      }),
      this.prisma.stripeDispute.count({ where: { ...where, status: "lost", evidenceSubmittedAt: null } }),
    ]);
    const stats: OutcomeStats = { won: 0, lost: 0, other: 0, winRatePct: null, wonAmount: {}, lostAmount: {}, lostUnanswered };
    for (const row of byStatusCurrency) {
      const count = row._count._all;
      const amount = row._sum.amount ?? 0;
      if (row.status === "won") {
        stats.won += count;
        stats.wonAmount[row.currency] = (stats.wonAmount[row.currency] ?? 0) + amount;
      } else if (row.status === "lost") {
        stats.lost += count;
        stats.lostAmount[row.currency] = (stats.lostAmount[row.currency] ?? 0) + amount;
      } else {
        stats.other += count;
      }
    }
    const decided = stats.won + stats.lost;
    stats.winRatePct = decided > 0 ? (stats.won / decided) * 100 : null;
    return stats;
  }

  // Win rate split by dispute reason (all-time), busiest reasons first.
  async statsByReason(): Promise<ReasonStats[]> {
    const rows = await this.prisma.stripeDispute.groupBy({
      by: ["reason", "status"],
      where: { status: { in: [...TERMINAL_STATUSES] } },
      _count: { _all: true },
    });
    const byReason = new Map<string, ReasonStats>();
    for (const row of rows) {
      const entry = byReason.get(row.reason) ?? { reason: row.reason, won: 0, lost: 0, other: 0, winRatePct: null };
      const count = row._count._all;
      if (row.status === "won") entry.won += count;
      else if (row.status === "lost") entry.lost += count;
      else entry.other += count;
      byReason.set(row.reason, entry);
    }
    const out = [...byReason.values()];
    for (const entry of out) {
      const decided = entry.won + entry.lost;
      entry.winRatePct = decided > 0 ? (entry.won / decided) * 100 : null;
    }
    return out.sort((a, b) => b.won + b.lost + b.other - (a.won + a.lost + a.other));
  }

  // Submitted-evidence snapshots from WON disputes, same reason preferred —
  // few-shot exemplars for the AI evidence draft.
  async wonEvidenceExemplars(reason: string, limit = 2): Promise<Array<{ reason: string; evidence: Record<string, string> }>> {
    const base = { status: "won", evidenceFinal: { not: Prisma.DbNull } } as const;
    const primary = await this.prisma.stripeDispute.findMany({
      where: { ...base, reason },
      orderBy: [{ closedAt: { sort: "desc", nulls: "last" } }],
      take: limit,
    });
    const rows = [...primary];
    if (rows.length < limit) {
      const fill = await this.prisma.stripeDispute.findMany({
        where: { ...base, reason: { not: reason } },
        orderBy: [{ closedAt: { sort: "desc", nulls: "last" } }],
        take: limit - rows.length,
      });
      rows.push(...fill);
    }
    return rows
      .map((r) => ({ reason: r.reason, evidence: (r.evidenceFinal ?? {}) as Record<string, string> }))
      .filter((r) => Object.keys(r.evidence).length > 0);
  }

  // Backfill export work-list: every terminal dispute in the mirror.
  async listTerminalForExport(): Promise<
    Array<
      Pick<
        StripeDispute,
        | "id"
        | "status"
        | "reason"
        | "amount"
        | "currency"
        | "closedAt"
        | "closedAtEstimated"
        | "closedAtSource"
        | "evidenceSubmittedAt"
        | "usdMinor"
        | "fxRate"
        // The descriptive axes, so a re-emit carries them without re-reading
        // Stripe. That is the whole point of mirroring them.
        | "planTier"
        | "planPeriod"
        | "cardBrand"
        | "cardFunding"
        | "cardCountry"
        | "networkReason"
        | "tenure"
      >
    >
  > {
    return this.prisma.stripeDispute.findMany({
      where: { status: { in: [...TERMINAL_STATUSES] } },
      select: {
        id: true,
        status: true,
        reason: true,
        amount: true,
        currency: true,
        closedAt: true,
        closedAtEstimated: true,
        closedAtSource: true,
        evidenceSubmittedAt: true,
        usdMinor: true,
        fxRate: true,
        planTier: true,
        planPeriod: true,
        cardBrand: true,
        cardFunding: true,
        cardCountry: true,
        networkReason: true,
        tenure: true,
      },
      orderBy: { closedAt: "asc" },
    });
  }

  // Terminal disputes whose row changed since a moment — the rebuild's tail
  // catch-up. A dispute that closed while emission was suppressed, or after the
  // re-emit had already read the mirror, would otherwise never reach Influx.
  async listTerminalChangedSince(since: Date): Promise<Awaited<ReturnType<DisputeStore["listTerminalForExport"]>>> {
    return this.prisma.stripeDispute.findMany({
      where: { status: { in: [...TERMINAL_STATUSES] }, updatedAt: { gte: since } },
      select: {
        id: true,
        status: true,
        reason: true,
        amount: true,
        currency: true,
        closedAt: true,
        closedAtEstimated: true,
        closedAtSource: true,
        evidenceSubmittedAt: true,
        usdMinor: true,
        fxRate: true,
        planTier: true,
        planPeriod: true,
        cardBrand: true,
        cardFunding: true,
        cardCountry: true,
        networkReason: true,
        tenure: true,
      },
      orderBy: { closedAt: "asc" },
    });
  }

  // Monthly buckets for the dashboard dispute-ratio trend chart.
  async countCreatedBetween(from: Date, to: Date): Promise<number> {
    return this.prisma.stripeDispute.count({
      where: { disputeCreatedAt: { gte: from, lt: to } },
    });
  }

  // Any-status mirror listing for the dashboard "All disputes" tab (listOpen
  // is open-statuses-only; this one defaults to EVERYTHING).
  async listMirror(
    skip: number,
    take: number,
    filter?: { status?: string; reason?: string; verdict?: "fight" | "accept" | "none" },
    sort: DisputeSort = "new"
  ): Promise<{ rows: StripeDispute[]; total: number }> {
    // The EFFECTIVE verdict: a human override wins over the rules, so a
    // dispute the rules call Accept but a human set to Fight lists as Fight.
    const verdictWhere: Prisma.StripeDisputeWhereInput | null =
      filter?.verdict === "none"
        ? { verdict: null, verdictOverride: null }
        : filter?.verdict
          ? {
              OR: [
                { verdictOverride: filter.verdict },
                { verdictOverride: null, verdict: filter.verdict },
              ],
            }
          : null;
    const where: Prisma.StripeDisputeWhereInput = {
      ...(filter?.status ? { status: filter.status } : {}),
      ...(filter?.reason ? { reason: filter.reason } : {}),
      ...(verdictWhere ?? {}),
    };
    const orderBy: Prisma.StripeDisputeOrderByWithRelationInput[] =
      sort === "amount"
        ? [{ amount: "desc" }, { disputeCreatedAt: "desc" }]
        : sort === "due"
          ? [{ evidenceDueBy: { sort: "asc", nulls: "last" } }, { disputeCreatedAt: "desc" }]
          : [{ disputeCreatedAt: "desc" }];
    const [rows, total] = await Promise.all([
      this.prisma.stripeDispute.findMany({ where, orderBy, skip, take }),
      this.prisma.stripeDispute.count({ where }),
    ]);
    return { rows, total };
  }

  // Status histogram for the dashboard count-cards + the nav badge.
  async countsByStatus(): Promise<Array<{ status: string; count: number }>> {
    const rows = await this.prisma.stripeDispute.groupBy({
      by: ["status"],
      _count: { _all: true },
    });
    return rows.map((r) => ({ status: r.status, count: r._count._all }));
  }

  async countOpen(): Promise<number> {
    return this.prisma.stripeDispute.count({ where: { status: { in: [...OPEN_DISPUTE_STATUSES] } } });
  }

  async countDueWithin(days: number, now: Date = new Date()): Promise<number> {
    return this.prisma.stripeDispute.count({
      where: {
        status: { in: [...RESPONDABLE_DISPUTE_STATUSES] },
        evidenceSubmittedAt: null,
        evidenceDueBy: { gte: now, lte: new Date(now.getTime() + days * DAY_MS) },
      },
    });
  }

  // Normal reminder work-list: respondable, unsubmitted, due within the lead
  // window but NOT yet inside the urgent window (that tier pings separately),
  // not pinged in the last 24h. Past-due excluded — the response window is over.
  // Records what the last templated pack produced. Deliberately does NOT touch
  // evidenceTouchedAt: the pack stages through the same method a human does,
  // and marking itself as touched would make it veto its own auto-submit.
  async recordAutoPack(
    disputeId: string,
    pack: { score: number; templateVersion: string; fields: unknown }
  ): Promise<void> {
    await this.prisma.stripeDispute.update({
      where: { id: disputeId },
      data: {
        evidenceAutoStagedAt: new Date(),
        evidenceAutoScore: pack.score,
        evidenceTemplateVersion: pack.templateVersion,
        evidenceAutoFields: pack.fields as Prisma.InputJsonValue,
      },
    });
  }

  // Stamped by the UI CALL SITES only (the Discord modals and the web panel
  // actions), never inside the shared evidence service. Once a human has typed
  // anything into a dispute they own it, and auto-submit stands down.
  async markEvidenceTouched(disputeId: string, actorId: string, actorName: string): Promise<void> {
    await this.prisma.stripeDispute
      .update({
        where: { id: disputeId },
        data: { evidenceTouchedAt: new Date(), evidenceTouchedBy: `${actorName} (${actorId})`.slice(0, 190) },
      })
      .catch(() => {
        // A dispute the mirror has not seen yet is not worth failing an edit over.
      });
  }

  // "Leave this one alone": a human opting a dispute out of auto-submit
  // entirely, without having to edit its evidence to do it.
  async setAutoOptOut(disputeId: string, optOut: boolean): Promise<void> {
    await this.prisma.stripeDispute.update({ where: { id: disputeId }, data: { evidenceAutoOptOut: optOut } });
  }

  // ---- fight-or-accept verdict ----

  // Writes the rules' latest verdict. The override columns are never touched
  // here: a recompute must not erase a human's disagreement with the rules.
  async recordVerdict(
    disputeId: string,
    v: {
      verdict: string;
      decisive: string;
      signals: unknown;
      complete: boolean;
      version: string;
      source: "live" | "backtest";
    },
    at: Date = new Date()
  ): Promise<StripeDispute | null> {
    const updated = await this.prisma.stripeDispute.updateMany({
      where: { id: disputeId },
      data: {
        verdict: v.verdict,
        verdictDecisive: v.decisive,
        verdictSignals: v.signals as Prisma.InputJsonValue,
        verdictComplete: v.complete,
        verdictVersion: v.version,
        verdictSource: v.source,
        verdictAt: at,
      },
    });
    if (updated.count === 0) return null;
    return this.get(disputeId);
  }

  async recordVerdictOverride(
    disputeId: string,
    o: { verdict: "fight" | "accept"; by: string; reason: string },
    at: Date = new Date()
  ): Promise<void> {
    await this.prisma.stripeDispute.updateMany({
      where: { id: disputeId },
      data: {
        verdictOverride: o.verdict,
        verdictOverrideBy: o.by.slice(0, 190),
        verdictOverrideReason: o.reason.slice(0, 1000),
        verdictOverrideAt: at,
      },
    });
  }

  // Open disputes still waiting on a response whose verdict is missing,
  // incomplete, from an older rule set, or older than staleBefore. Most urgent
  // first, so a capped tick spends itself on the deadlines that matter.
  async listNeedingVerdict(version: string, staleBefore: Date, take: number): Promise<StripeDispute[]> {
    return this.prisma.stripeDispute.findMany({
      where: {
        status: { in: [...RESPONDABLE_DISPUTE_STATUSES] },
        evidenceSubmittedAt: null,
        // `not` never matches NULL in SQL, so a missing version is spelled out.
        OR: [
          { verdict: null },
          { verdictComplete: false },
          { verdictVersion: null },
          { verdictVersion: { not: version } },
          { verdictAt: null },
          { verdictAt: { lt: staleBefore } },
        ],
      },
      orderBy: [{ evidenceDueBy: { sort: "asc", nulls: "last" } }, { disputeCreatedAt: "asc" }],
      take,
    });
  }

  // How fights on this reason have gone: decided disputes where evidence
  // actually reached the bank. The context a verdict is read in.
  async foughtRecordForReason(reason: string): Promise<{ won: number; lost: number }> {
    const where = { reason, evidenceSubmittedAt: { not: null } };
    const [won, lost] = await Promise.all([
      this.prisma.stripeDispute.count({ where: { ...where, status: "won" } }),
      this.prisma.stripeDispute.count({ where: { ...where, status: "lost" } }),
    ]);
    return { won, lost };
  }

  // The backtest's population: formal chargebacks that reached a decision
  // (won or lost) since a cutoff. Inquiries are left out on purpose, because a
  // refund, not a fight, is what closes those.
  private backtestScope(since: Date): Prisma.StripeDisputeWhereInput {
    return { status: { in: ["won", "lost"] }, disputeCreatedAt: { gte: since } };
  }

  // Closed disputes the backtest still has to evaluate: never evaluated, or
  // evaluated by an older rule set. A verdict made while the dispute was LIVE
  // is never recomputed, because that is the verdict that was actually shown.
  async listBacktestCandidates(
    version: string,
    since: Date,
    take: number,
    excludeIds: string[] = []
  ): Promise<StripeDispute[]> {
    return this.prisma.stripeDispute.findMany({
      where: {
        ...this.backtestScope(since),
        OR: [
          { verdict: null },
          { verdictSource: "backtest", verdictVersion: null },
          { verdictSource: "backtest", verdictVersion: { not: version } },
        ],
        ...(excludeIds.length ? { id: { notIn: excludeIds } } : {}),
      },
      orderBy: { disputeCreatedAt: "desc" },
      take,
    });
  }

  // A re-run re-decides every backtest verdict under the CURRENT settings (the
  // thin-data bar is one), not only those from an older rule set. Live
  // verdicts are untouched: they are what was actually shown at the time.
  async resetBacktestVerdicts(): Promise<number> {
    const r = await this.prisma.stripeDispute.updateMany({
      where: { verdictSource: "backtest" },
      data: { verdictVersion: null },
    });
    return r.count;
  }

  async backtestProgress(version: string, since: Date): Promise<{ eligible: number; done: number }> {
    const scope = this.backtestScope(since);
    const [eligible, done] = await Promise.all([
      this.prisma.stripeDispute.count({ where: scope }),
      this.prisma.stripeDispute.count({
        where: {
          ...scope,
          verdict: { not: null },
          OR: [{ verdictSource: "live" }, { verdictVersion: version }],
        },
      }),
    ]);
    return { eligible, done };
  }

  // Fought vs unanswered outcomes, grouped by one descriptive axis. "Fought"
  // means evidence reached the bank; a dispute lost without any is a loss we
  // chose (or missed), not one the evidence lost.
  async lossBreakdown(axis: LossAxis): Promise<
    Array<{ key: string; foughtWon: number; foughtLost: number; unanswered: number; ids: string[] }>
  > {
    const rows = await this.prisma.stripeDispute.findMany({
      where: { status: { in: ["won", "lost"] } },
      select: {
        id: true,
        status: true,
        evidenceSubmittedAt: true,
        reason: true,
        networkReason: true,
        cardBrand: true,
        verdict: true,
        verdictOverride: true,
        verdictDecisive: true,
      },
      take: 5000,
    });
    const keyOf = (r: (typeof rows)[number]): string | null => {
      switch (axis) {
        case "reason":
          return r.reason;
        case "networkReason":
          return r.networkReason;
        case "cardBrand":
          return r.cardBrand;
        case "verdict":
          return r.verdictOverride ?? r.verdict ?? "none";
        case "decisive":
          return r.verdict ? r.verdictDecisive : "none";
      }
    };
    const groups = new Map<string, { key: string; foughtWon: number; foughtLost: number; unanswered: number; ids: string[] }>();
    for (const r of rows) {
      const key = keyOf(r) || "unknown";
      const g = groups.get(key) ?? { key, foughtWon: 0, foughtLost: 0, unanswered: 0, ids: [] };
      if (!r.evidenceSubmittedAt) g.unanswered++;
      else if (r.status === "won") g.foughtWon++;
      else g.foughtLost++;
      g.ids.push(r.id);
      groups.set(key, g);
    }
    return [...groups.values()].sort(
      (a, b) => b.foughtWon + b.foughtLost + b.unanswered - (a.foughtWon + a.foughtLost + a.unanswered)
    );
  }

  // Respondable, unsubmitted, not opted out, and inside the auto-submit window.
  // The looper's enrich-and-submit work list.
  async listNeedingAutoEvidence(withinHours: number, now: Date = new Date()): Promise<StripeDispute[]> {
    return this.prisma.stripeDispute.findMany({
      where: {
        status: { in: [...RESPONDABLE_DISPUTE_STATUSES] },
        evidenceSubmittedAt: null,
        evidenceAutoOptOut: false,
        evidenceDueBy: { gt: now, lte: new Date(now.getTime() + withinHours * 3_600_000) },
      },
      orderBy: { evidenceDueBy: "asc" },
    });
  }

  // How many disputes this customer has raised since a cutoff, excluding the
  // one being evaluated. The repeat-offender half of the auto-resolve guardrail:
  // refunding somebody their second dispute in a quarter teaches them the route
  // works, so those get escalated to a human instead.
  async countForCustomerSince(customerId: string, since: Date, excludeDisputeId: string | null): Promise<number> {
    return this.prisma.stripeDispute.count({
      where: {
        customerId,
        disputeCreatedAt: { gte: since },
        ...(excludeDisputeId ? { id: { not: excludeDisputeId } } : {}),
      },
    });
  }

  async listNeedingReminder(withinDays: number, urgentHours: number, now: Date = new Date()): Promise<StripeDispute[]> {
    const urgentEdge = new Date(now.getTime() + urgentHours * 3600_000);
    const leadEdge = new Date(now.getTime() + withinDays * DAY_MS);
    if (urgentEdge >= leadEdge) return []; // urgent window swallows the whole lead window
    return this.prisma.stripeDispute.findMany({
      where: {
        status: { in: [...RESPONDABLE_DISPUTE_STATUSES] },
        evidenceSubmittedAt: null,
        evidenceDueBy: { gt: urgentEdge, lte: leadEdge },
        OR: [{ lastReminderAt: null }, { lastReminderAt: { lt: new Date(now.getTime() - DAY_MS) } }],
      },
      orderBy: { evidenceDueBy: "asc" },
    });
  }

  // Urgent work-list: due within urgentHours, still respondable + unsubmitted.
  // Separate 24h damper so a dispute that already got a normal reminder still
  // escalates the moment it enters the urgent window.
  async listNeedingUrgentReminder(urgentHours: number, now: Date = new Date()): Promise<StripeDispute[]> {
    return this.prisma.stripeDispute.findMany({
      where: {
        status: { in: [...RESPONDABLE_DISPUTE_STATUSES] },
        evidenceSubmittedAt: null,
        evidenceDueBy: { gte: now, lte: new Date(now.getTime() + urgentHours * 3600_000) },
        OR: [{ lastUrgentReminderAt: null }, { lastUrgentReminderAt: { lt: new Date(now.getTime() - DAY_MS) } }],
      },
      orderBy: { evidenceDueBy: "asc" },
    });
  }

  async recordReminder(id: string): Promise<void> {
    await this.prisma.stripeDispute.updateMany({ where: { id }, data: { lastReminderAt: new Date() } });
  }

  async recordUrgentReminder(id: string): Promise<void> {
    await this.prisma.stripeDispute.updateMany({ where: { id }, data: { lastUrgentReminderAt: new Date() } });
  }

  // Group modals and the evidence pack save one field subset at a time, so they merge into
  // the existing draft so saving "Policies" doesn't wipe the "Core" draft.
  async mergeEvidenceDraft(id: string, patch: Record<string, string>): Promise<void> {
    const row = await this.prisma.stripeDispute.findUnique({ where: { id }, select: { evidenceDraft: true } });
    const merged = { ...((row?.evidenceDraft ?? {}) as Record<string, string>), ...patch };
    await this.prisma.stripeDispute.updateMany({ where: { id }, data: { evidenceDraft: merged } });
  }

  async markSubmitted(id: string): Promise<void> {
    await this.prisma.stripeDispute.updateMany({ where: { id }, data: { evidenceSubmittedAt: new Date() } });
  }

  // Reconciliation: local-open ids to re-check against Stripe (catches closes
  // older than the sweep window and missed webhooks).
  async listOpenIds(): Promise<string[]> {
    const rows = await this.prisma.stripeDispute.findMany({
      where: { status: { in: [...OPEN_DISPUTE_STATUSES] } },
      select: { id: true },
    });
    return rows.map((r) => r.id);
  }

  // Overview footer context: outcome tallies of NON-open disputes created in
  // the trailing window (won / lost / prevented+closed-inquiry).
  async closedSummarySince(days: number, now: Date = new Date()): Promise<{ won: number; lost: number; otherClosed: number }> {
    const rows = await this.prisma.stripeDispute.groupBy({
      by: ["status"],
      where: {
        status: { notIn: [...OPEN_DISPUTE_STATUSES] },
        disputeCreatedAt: { gte: new Date(now.getTime() - days * DAY_MS) },
      },
      _count: { _all: true },
    });
    const summary = { won: 0, lost: 0, otherClosed: 0 };
    for (const row of rows) {
      const count = row._count._all;
      if (row.status === "won") summary.won += count;
      else if (row.status === "lost") summary.lost += count;
      else summary.otherClosed += count;
    }
    return summary;
  }

  // ---- Watch subscriptions (DM on status change) ----

  async watch(disputeId: string, userId: string): Promise<void> {
    try {
      await this.prisma.disputeWatch.create({ data: { disputeId, userId } });
    } catch (error) {
      if ((error as { code?: string }).code !== "P2002") throw error; // already watching
    }
  }

  async unwatch(disputeId: string, userId: string): Promise<void> {
    await this.prisma.disputeWatch.deleteMany({ where: { disputeId, userId } });
  }

  async isWatching(disputeId: string, userId: string): Promise<boolean> {
    return (await this.prisma.disputeWatch.findFirst({ where: { disputeId, userId } })) !== null;
  }

  async watchers(disputeId: string): Promise<string[]> {
    const rows = await this.prisma.disputeWatch.findMany({ where: { disputeId }, select: { userId: true } });
    return rows.map((r) => r.userId);
  }
}

